// Step 2: Data Structure Validation for Legal Document Analysis
// This code validates incoming form data and ensures it matches our expected schema

// First, let's extract the incoming data from the webhook
// Based on Step 1 findings, form data is nested in the 'body' property
const incomingData = $input.first().json;

// Initialize our validation results object
const validationResult = {
  isValid: false,
  errors: [],
  validatedData: null,
  processingTimestamp: new Date().toISOString()
};

// Check if the basic structure exists
// We expect data to be in incomingData.body based on Step 1 findings
if (!incomingData.body) {
  validationResult.errors.push("Missing form data structure. Expected 'body' property not found.");
  return [{ json: validationResult }];
}

const formData = incomingData.body;

// Validate required fields according to Form_Output_Documentation.md
// Required fields: clientName and attorneyName
const requiredFields = ['clientName', 'attorneyName'];

for (const field of requiredFields) {
  if (!formData[field]) {
    validationResult.errors.push(`Missing required field: ${field}`);
  } else if (typeof formData[field] !== 'string') {
    validationResult.errors.push(`Field ${field} must be a string`);
  } else if (formData[field].trim().length === 0) {
    validationResult.errors.push(`Field ${field} cannot be empty`);
  }
}

// Validate optional field (caseReference) if present
if (formData.caseReference && typeof formData.caseReference !== 'string') {
  validationResult.errors.push("Field caseReference must be a string");
}

// If we have errors, return them immediately
if (validationResult.errors.length > 0) {
  validationResult.isValid = false;
  return [{ json: validationResult }];
}

// If validation passes, prepare clean data structure
const cleanData = {
  clientName: formData.clientName.trim(),
  caseReference: formData.caseReference ? formData.caseReference.trim() : '',
  attorneyName: formData.attorneyName.trim()
};

// Set success status and return validated data
validationResult.isValid = true;
validationResult.validatedData = cleanData;
validationResult.message = "Form data validation successful";

return [{ json: validationResult }];

// Step 3: Intake Form Data Processing
// This node structures the validated intake form data into a standardized format
// Based on the established pattern from the proposed workflow's caseInfo structure

const validationData = $input.first().json;

// Only process if validation was successful
if (!validationData.isValid) {
  // Pass through validation errors unchanged
  return [{ json: validationData }];
}

// Extract the clean validated data
const validatedFields = validationData.validatedData;

// Structure the intake form data into standardized JSON format
// Following the caseInfo pattern from the proposed workflow
const structuredIntakeData = {
  caseInfo: {
    clientName: validatedFields.clientName,
    caseReference: validatedFields.caseReference || `CASE-${new Date().toISOString().split('T')[0]}`,
    attorneyName: validatedFields.attorneyName,
    processingDate: new Date().toISOString()
  },
  dataProcessingStatus: {
    intakeFormProcessed: true,
    structuredAt: new Date().toISOString(),
    dataQuality: 'validated'
  },
  nextStage: 'document-processing'
};

// Return the structured data with success metadata
return [{
  json: {
    isValid: true,
    structuredData: structuredIntakeData,
    processingTimestamp: validationData.processingTimestamp,
    message: 'Intake form data successfully structured for processing'
  }
}];

// Extract all binary files (intakeForm + caseDocument*) from Webhook
const intakeResult = $input.first().json;
const structuredData = intakeResult.structuredData; // passed along
const webhookItems = $items('Webhook'); // get ALL files from Webhook node

const outputs = [];
try {
  const intakeResult = $input.first().json;
  const structuredData = intakeResult.structuredData;
  const webhookItems = $items('Webhook');

  for (const item of webhookItems) {
    const binary = item.binary || {};

  for (const [key, bin] of Object.entries(binary)) {
    if (!bin?.data) continue;

    const isIntake = key === 'intakeForm';

    outputs.push({
      json: {
        documentType: isIntake ? 'intakeForm' : 'caseDocument',
        documentId: isIntake ? 'intake-form' : key,
        meta: {
          fileName: bin.fileName,
          mimeType: bin.mimeType,
          fileSize: bin.fileSize
        },
        structuredData
      },
      binary: {
        data: bin
      }
    });
  }
  }
  return outputs;
} catch (error) {
  console.error('Error processing binary files:', error);
  return [{ json: { error: error.message } }];
}

// In Filter PDFs
const inputItems = $input.all();
const pdfItems = inputItems.filter(item => {
  const mimeType = item.json.meta?.mimeType;
  if (!mimeType) {
    console.warn('Item missing mimeType:', item.json);
    return false;
  }
  return mimeType === 'application/pdf';
});

if (pdfItems.length === 0) {
  throw new Error('No PDF files found to process');
}

return pdfItems;

const outputs = [];

for (const item of $input.all()) {
  const structuredFromNode = item.json?.structuredData || {};
  const data = item.json ?? {};
  const documentType = data.documentType || 'intakeForm';

  const formFields = Array.isArray(data.formFields) ? data.formFields : (Array.isArray(data?.body?.FieldsInfo?.Fields) ? data.body.FieldsInfo.Fields : []);
  const text = typeof data.text === 'string' ? data.text : '';

  const fieldMap = Object.fromEntries(formFields.map(f => [String(f.FieldName || '').trim(), f.Value ?? '']));

  const sdCase = structuredFromNode.caseInfo || {};
  const clientName = sdCase.clientName || '';
  const attorneyName = sdCase.attorneyName || '';
  const caseRef = sdCase.caseReference || '';

  const clientNameFromFields = fieldMap['Client Name'] || fieldMap['clientName'] || clientName;
  const attorneyNameFromFields = fieldMap['Attorney Name'] || fieldMap['attorneyName'] || attorneyName;
  const caseRefFromFields = fieldMap['Case Reference'] || fieldMap['caseReference'] || caseRef;

  const promptText = `Analyze the following legal document and extract key information.\nDocument Type: ${documentType}\nClient Name: ${clientNameFromFields}\nAttorney Name: ${attorneyNameFromFields}\nCase Reference: ${caseRefFromFields}\n\nDocument Content:\n${text}\n\nForm Fields:\n${JSON.stringify(fieldMap, null, 2)}\n\nPlease structure the output in JSON format with the following keys: 'summary', 'keyFacts', 'partiesInvolved', 'potentialIssues'.`;

  outputs.push({
    json: {
      aiPrompt: promptText,
      documentType: documentType,
      structuredData: structuredFromNode
    }
  });
}

return outputs;

// This node ensures 'documentType' is preserved after the OpenAI call.
const openAIResult = $input.first().json;
const originalData = $items('Build AI Prompt')[0].json;

return [{
  json: {
    ...openAIResult,
    documentType: originalData.documentType
  }
}];

// Merge Validator Node
// This node validates the merged case data structure and adds final validation metadata
// Ensures the unified case file meets all quality requirements

// Get the input data from the Case Data Merger node
const inputData = $input.first().json;

// Initialize validation result
const validationResult = {
  isValid: true,
  errors: [],
  validatedUnifiedCaseFile: null,
  processingTimestamp: new Date().toISOString(),
  validationMetadata: {
    nodeType: "merge-validator",
    validationLevel: "final",
    validationRules: [
      "unified_structure_check",
      "required_fields_validation",
      "data_integrity_check",
      "processing_status_validation"
    ],
    validationStatus: "processing"
  }
};

// Validate that we received valid merge data
if (!inputData || !inputData.isValid) {
  validationResult.isValid = false;
  validationResult.errors.push("Invalid input: Previous merge step failed");
  if (inputData && inputData.errors) {
    validationResult.errors = validationResult.errors.concat(inputData.errors);
  }
  return [{ json: validationResult }];
}

// Extract the unified case file
const unifiedCaseFile = inputData.unifiedCaseFile;
if (!unifiedCaseFile) {
  validationResult.isValid = false;
  validationResult.errors.push("No unified case file found in merge result");
  return [{ json: validationResult }];
}

// Validation Rule 1: Unified Structure Check
const requiredTopLevelFields = ['caseId', 'createdAt', 'status', 'caseInfo', 'intakeFormData', 'caseDocumentsAnalysis', 'processingSummary'];
const missingFields = [];

for (const field of requiredTopLevelFields) {
  if (!unifiedCaseFile.hasOwnProperty(field)) {
    missingFields.push(field);
  }
}

if (missingFields.length > 0) {
  validationResult.isValid = false;
  validationResult.errors.push(`Missing required top-level fields: ${missingFields.join(', ')}`);
}

// Validation Rule 2: Required Fields Validation
if (!unifiedCaseFile.caseId || typeof unifiedCaseFile.caseId !== 'string') {
  validationResult.isValid = false;
  validationResult.errors.push("caseId must be a non-empty string");
}

if (!unifiedCaseFile.createdAt || typeof unifiedCaseFile.createdAt !== 'string') {
  validationResult.isValid = false;
  validationResult.errors.push("createdAt must be a valid timestamp string");
}

if (!unifiedCaseFile.status || !['completed', 'partial_success', 'failed'].includes(unifiedCaseFile.status)) {
  validationResult.isValid = false;
  validationResult.errors.push("status must be one of: completed, partial_success, failed");
}

// Validation Rule 3: Data Integrity Check
if (!unifiedCaseFile.processingSummary || typeof unifiedCaseFile.processingSummary !== 'object') {
  validationResult.isValid = false;
  validationResult.errors.push("processingSummary must be an object");
} else {
  const summary = unifiedCaseFile.processingSummary;

  if (typeof summary.totalBranchesProcessed !== 'number' || summary.totalBranchesProcessed < 0) {
    validationResult.isValid = false;
    validationResult.errors.push("processingSummary.totalBranchesProcessed must be a non-negative number");
  }

  if (typeof summary.successfulBranches !== 'number' || summary.successfulBranches < 0) {
    validationResult.isValid = false;
    validationResult.errors.push("processingSummary.successfulBranches must be a non-negative number");
  }

  if (typeof summary.failedBranches !== 'number' || summary.failedBranches < 0) {
    validationResult.isValid = false;
    validationResult.errors.push("processingSummary.failedBranches must be a non-negative number");
  }

  // Validate that the sum matches total
  if (summary.successfulBranches + summary.failedBranches !== summary.totalBranchesProcessed) {
    validationResult.isValid = false;
    validationResult.errors.push("processingSummary branch counts do not add up correctly");
  }
}

// Validation Rule 4: Processing Status Validation
if (!unifiedCaseFile.intakeFormData || typeof unifiedCaseFile.intakeFormData !== 'object') {
  validationResult.isValid = false;
  validationResult.errors.push("intakeFormData must be an object");
} else {
  const intakeStatus = unifiedCaseFile.intakeFormData.status;
  if (!['processed', 'failed', 'not_processed'].includes(intakeStatus)) {
    validationResult.isValid = false;
    validationResult.errors.push("intakeFormData.status must be one of: processed, failed, not_processed");
  }
}

if (!unifiedCaseFile.caseDocumentsAnalysis || typeof unifiedCaseFile.caseDocumentsAnalysis !== 'object') {
  validationResult.isValid = false;
  validationResult.errors.push("caseDocumentsAnalysis must be an object");
} else {
  const caseDocsStatus = unifiedCaseFile.caseDocumentsAnalysis.status;
  if (!['processed', 'failed', 'not_processed'].includes(caseDocsStatus)) {
    validationResult.isValid = false;
    validationResult.errors.push("caseDocumentsAnalysis.status must be one of: processed, failed, not_processed");
  }
}

// If validation passes, add final validation metadata
if (validationResult.errors.length === 0) {
  const finalValidatedCaseFile = {
    ...unifiedCaseFile,
    finalValidation: {
      validatedAt: new Date().toISOString(),
      validationLevel: "final",
      validationStatus: "passed",
      validatorVersion: "1.0.0",
      originalMergeTimestamp: inputData.processingTimestamp,
      mergeMetadata: inputData.mergeMetadata || {}
    }
  };

  validationResult.validatedUnifiedCaseFile = finalValidatedCaseFile;
  validationResult.validationMetadata.validationStatus = "completed";
  validationResult.message = "Unified case file successfully validated and finalized";
} else {
  validationResult.isValid = false;
  validationResult.validationMetadata.validationStatus = "failed";
}

// Preserve original merge data for reference
validationResult.originalMergeData = {
  mergeResult: inputData,
  mergeTimestamp: inputData.processingTimestamp
};

// Return the validation result
return [{ json: validationResult }];

// Format Email Response - Get case info from Prepare Email Prompt node
const emailContent = $input.first().json.message.content;

// Get the case info from the Prepare Email Prompt node (not current input)
const prepareEmailData = $items("Prepare Email Prompt")[0]?.json || {};
const clientName = prepareEmailData.clientName || "Client";
const attorneyName = prepareEmailData.attorneyName || "Attorney";
const caseReference = prepareEmailData.caseReference || "CASE-UNKNOWN";

// Get case file for additional metadata, guarding against missing values
const mergeValidatorData = $items("Merge Validator")[0]?.json || {};
const caseFile = mergeValidatorData.validatedUnifiedCaseFile || {};
const caseId = caseFile.caseId || "UNKNOWN_CASE_ID";

// Clean up the email content
let emailBody = emailContent.replace(/^```\\s*|```\\s*$/g, '').trim();

// Extract subject if present
let subject = `Legal Analysis Findings - ${caseReference}`;
const subjectMatch = emailBody.match(/Subject:\\s*(.+)/i);
if (subjectMatch) {
  subject = subjectMatch[1].trim();
  emailBody = emailBody.replace(/Subject:\\s*.+\\n?/i, '').trim();
}

// Create email file content with ACTUAL values
const currentDate = new Date();
const attorneyEmail = attorneyName.toLowerCase().replace(/[^a-z]/g, '') + '@brflorida.com';
const clientEmail = clientName.toLowerCase().replace(/[^a-z]/g, '') + '@client.com';

const emlContent = `From: ${attorneyName} <${attorneyEmail}>\nTo: ${clientName} <${clientEmail}>\nSubject: ${subject}\nDate: ${currentDate.toUTCString()}\nMIME-Version: 1.0\nContent-Type: text/plain; charset=utf-8\n\n${emailBody}\n\n---\nGenerated by Legal Document Analysis Portal\nCase ID: ${caseId}\nProcessed: ${currentDate.toISOString()}`;

// Create downloadable files
const emlBase64 = Buffer.from(emlContent, 'utf8').toString('base64');
const txtBase64 = Buffer.from(emailBody, 'utf8').toString('base64');

const cleanCaseRef = caseReference.replace(/[^a-zA-Z0-9]/g, '_');
const dateStr = currentDate.toISOString().split('T')[0];

return [{
  json: {
    status: "success",
    message: `✅ Legal Analysis Complete! Generated findings email for ${clientName}.`,
    documentsProcessed: 2,
    downloadLinks: {
      findingsLetter: `data:message/rfc822;base64,${emlBase64}`,
      caseAnalysis: `data:text/plain;base64,${txtBase64}`,
      executiveSummary: `data:text/plain;base64,${txtBase64}`
    },
    emailDetails: {
      subject: subject,
      from: `${attorneyName} <${attorneyEmail}>`,
      to: `${clientName} <${clientEmail}>`,
      emlFileName: `Findings_${cleanCaseRef}_${dateStr}.eml`
    },
    caseInfo: {
      caseId: caseId,
      clientName: clientName,
      attorneyName: attorneyName,
      caseReference: caseReference
    },
    analysisComplete: true,
    readyForDownload: true
  }
}];

// Enhanced Prepare Email Prompt with Complete Data Access
const inputData = $input.first().json || {};
const caseFile = inputData.validatedUnifiedCaseFile || {};

// Access intake data with enhanced fallback logic
let intake = {};
let clientName = 'Client';
let attorneyName = 'Attorney';  
let caseReference = 'CASE-001';

if (caseFile && typeof caseFile === 'object') {
  // Primary: Try to get from processed intake data
  if (caseFile.intakeFormData && caseFile.intakeFormData.data) {
    intake = caseFile.intakeFormData.data;
    clientName = intake.clientInfo?.clientName || clientName;
    attorneyName = intake.attorneyInfo?.attorneyName || attorneyName;
    caseReference = intake.caseInfo?.caseReference || caseReference;
  }

  // Secondary: Try to get from caseInfo (fallback populated in merger)
  if (caseFile.caseInfo) {
    clientName = caseFile.caseInfo.clientName || clientName;
    attorneyName = caseFile.caseInfo.attorneyName || attorneyName;
    caseReference = caseFile.caseInfo.caseReference || caseReference;
  }

  // Tertiary: Check if fallback was used in processing details
  if (caseFile.intakeFormData?.processingDetails?.fallbackUsed && caseFile.intakeFormData?.processingDetails?.fallbackData) {
    const fallbackData = caseFile.intakeFormData.processingDetails.fallbackData;
    clientName = fallbackData.clientName || clientName;
    attorneyName = fallbackData.attorneyName || attorneyName;
    caseReference = fallbackData.caseReference || caseReference;
  }
}

// Build comprehensive case details with both branches
let caseDetails = `This case involves ${clientName}. Processing Results:\\n`;

// Intake processing status
if (caseFile.intakeFormData) {
  caseDetails += `- Intake form: ${caseFile.intakeFormData.status}`;
  if (caseFile.intakeFormData.status === "failed" && caseFile.intakeFormData.processingDetails?.fallbackUsed) {
    caseDetails += ` (using fallback data)`;
  }
  caseDetails += `\\n`;
}

// Case documents processing status  
if (caseFile.caseDocumentsAnalysis) {
  caseDetails += `- Case documents: ${caseFile.caseDocumentsAnalysis.status}\\n`;
}

// Add processing summary
if (caseFile.processingSummary) {
  caseDetails += `\\nProcessing Summary: ${caseFile.processingSummary.successfulBranches} of ${caseFile.processingSummary.totalBranchesProcessed} branches completed successfully.`;
}

// Enhanced prompt with better context
const emailPrompt = `Write a professional legal findings email using these EXACT values:\n\nCLIENT NAME: ${clientName}\nATTORNEY NAME: ${attorneyName}  \nCASE REFERENCE: ${caseReference}\n\nIMPORTANT: Use the actual names above, NOT template variables.\n\nCase Processing Information:\n${caseDetails}\n\nWrite a professional legal findings email that:\n1. Uses the EXACT names provided above\n2. Acknowledges the current processing status  \n3. Provides appropriate guidance based on available information\n4. Maintains professional tone regardless of processing completeness\n5. Indicates if additional documents may improve the analysis\n\nFormat:\nSubject: Legal Analysis Findings - ${caseReference}\n\nDear ${clientName},\n\nI have completed the initial analysis of your legal matter (Case Reference: ${caseReference}). \n\n[Professional content based on available data]\n\nPlease let me know if you have any questions or if additional documentation becomes available.\n\nSincerely,\n${attorneyName}\nBernhardt Riley Attorneys at Law`;

return [{
  json: {
    emailPrompt,
    clientName,
    attorneyName,
    caseReference,
    originalData: inputData,
    processingMetadata: {
      caseStatus: caseFile.status || 'unknown',
      intakeStatus: caseFile.intakeFormData?.status || 'unknown',
      documentsStatus: caseFile.caseDocumentsAnalysis?.status || 'unknown'
    }
  }
}];

// Final Response Formatter
// Ensures clean JSON response for frontend

const responseData = $input.first().json;

// Return the data in the exact format needed for the webhook response
return [{ json: responseData }];

// Debug what data is being sent to OpenAI
const inputData = $input.first().json;

console.log("=== PROMPT DEBUG ===");
console.log("Client Name:", inputData.clientName);
console.log("Attorney Name:", inputData.attorneyName);
console.log("Case Reference:", inputData.caseReference);
console.log("Email Prompt Length:", inputData.emailPrompt ? inputData.emailPrompt.length : "NO PROMPT");
console.log("Original Data Keys:", Object.keys(inputData.originalData || {}));

// Show first 500 chars of prompt
if (inputData.emailPrompt) {
  console.log("Prompt Preview:", inputData.emailPrompt.substring(0, 500) + "...");
}

// Check if case file has actual document data
const caseFile = inputData.originalData?.validatedUnifiedCaseFile;
if (caseFile) {
  console.log("=== CASE FILE DEBUG ===");
  console.log("Intake Status:", caseFile.intakeFormData?.status);
  console.log("Documents Status:", caseFile.caseDocumentsAnalysis?.status);

  if (caseFile.intakeFormData?.data) {
    console.log("Intake Data:", JSON.stringify(caseFile.intakeFormData.data, null, 2));
  }

  if (caseFile.caseDocumentsAnalysis?.data) {
    console.log("Document Analysis:", JSON.stringify(caseFile.caseDocumentsAnalysis.data, null, 2));
  }
}

// Pass through unchanged
return [{ json: inputData }];
